"""Combine the JSON written by the training scripts into results.md for the chapter to quote."""

import json
from pathlib import Path

OUT = Path("experiments/p02_mlp")
mnist = json.loads((OUT / "results_mnist.json").read_text())
loc = json.loads((OUT / "results_location.json").read_text())

lines = [
    "# Phase 2 results",
    "",
    "Generated by `write_results.py` from the JSON files the training scripts produce.",
    "",
]
lines += ["## MNIST (`train_mnist.py`)", ""]
lines += [f"- **{k}**: {v}" for k, v in mnist.items() if not isinstance(v, dict)]
lines += [
    "",
    "Optimizer comparison, 5 epochs each:",
    "",
    "| optimizer | val loss | val acc |",
    "|---|---|---|",
]
lines += [
    f"| {k} | {v['val_loss']} | {v['val_acc']} |"
    for k, v in mnist["optimizer_comparison_5_epochs"].items()
]
o = mnist["overfit_500_images"]
lines += [
    "",
    f"Overfitting run on 500 images: best validation loss at epoch {o['best_val_epoch']}, "
    f"final train loss {o['final_train_loss']}, final val loss {o['final_val_loss']}, "
    f"final val acc {o['final_val_acc']}.",
    "",
]
lines += ["## Diary renders (`train_location.py`)", ""]
lines += [f"- **{k}**: {v}" for k, v in loc.items() if not isinstance(v, dict)]
lines += [
    "",
    "Same recipe on every attribute:",
    "",
    "| attribute | classes | chance | test acc |",
    "|---|---|---|---|",
]
for a, acc in loc["test_acc_per_attribute"].items():
    chance = loc["chance_per_attribute"][a]
    lines += [f"| {a} | {round(1 / chance)} | {chance:.3f} | {acc} |"]
(OUT / "results.md").write_text("\n".join(lines) + "\n")
print((OUT / "results.md").read_text())
